package com.braseiro.dnd5e;

import org.json.JSONArray;
import org.json.JSONObject;
import java.text.Normalizer;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * Planeja localmente a batida da cena. Não narra e não consome Gemini.
 * O modelo recebe uma decisão estruturada, não todo o trabalho do Mestre.
 */
public final class MasterCognitiveEngine {
    private final AppDb db;
    private final PartyDirector party;
    private final MasterRulesArbiter rules;
    public MasterCognitiveEngine(AppDb database,PartyDirector partyDirector,MasterRulesArbiter arbiter){db=database;party=partyDirector;rules=arbiter;}

    public JSONObject plan(String action,JSONObject localTick){/*BR_JSON_WRAP*/try{
        JSONObject out=new JSONObject();try{
            String n=normalize(action);String mode=resolvedSceneMode(n);JSONObject scene=db.getSceneState();JSONObject runtime=db.getMasterRuntimeState();
            JSONArray units=actionUnits(action);JSONArray actors=actors(units,n);int tension=tension(n,scene,runtime,mode);
            out.put("scene_mode",mode);out.put("tension",tension);out.put("actors",actors);out.put("action_units",causalOrder(units));out.put("subgroups",parseArray(db.getPartyState().optString("subgroups_json","[]")));out.put("limited_resource_policy",parseObject(db.getPartyState().optString("session_preferences_json","{}")).optString("limited_resource_policy","Sempre confirmar recursos limitados"));out.put("local_rules_frame",rules.rulesFrame(action));out.put("spotlight_hint",party.nextSpotlightHint());out.put("scene_goal",sceneGoal(mode,scene,tension));out.put("pacing",pacing(mode,tension));out.put("agency_guard","Nunca decida ação, fala decisiva, gasto de recurso limitado ou escolha moral por herói em modo manual. Em modo assistido, apenas sugira. Em modo companheiro/automático, obedeça tactics e pare antes de recurso importante.");out.put("test_guard","No máximo um teste pendente por unidade causal. Não role nem aplique consequência de teste ainda não realizado.");out.put("world_preview",localTick==null?new JSONObject():localTick);out.put("response_budget",new JSONObject().put("options_max",2).put("narration_style",mode.equals("combate")?"direta e espacial":mode.equals("conversa")?"diálogo responsivo":"imersiva sem recapitulação").put("no_recap",true));out.put("unresolved_threads",parseArray(runtime.optString("unresolved_threads_json","[]")));
        }catch(Exception ignored){AppLog.ignored("MasterCognitiveEngine","Falha tolerada; a execução continuou.",ignored);}return out;
    }catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}

    public JSONObject diagnostic(){/*BR_JSON_WRAP*/try{JSONObject out=new JSONObject();try{JSONObject state=db.getMasterRuntimeState();out.put("runtime_present",state.length()>0);out.put("beat_no",state.optInt("beat_no"));out.put("scene_mode",state.optString("scene_mode"));out.put("tension",state.optInt("tension"));out.put("active",true);}catch(Exception ignored){AppLog.ignored("MasterCognitiveEngine","Falha tolerada; a execução continuou.",ignored);}return out;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}

    private JSONArray actionUnits(String action){/*BR_JSON_WRAP*/try{JSONArray queued=party.queuedActions();if(queued.length()>0){JSONArray out=new JSONArray();for(int i=0;i<queued.length();i++){JSONObject q=queued.optJSONObject(i);if(q==null)continue;JSONObject x=new JSONObject();try{long actorId=q.optLong("character_id",0);x.put("actor_id",actorId);x.put("actor",q.optString("character_name"));x.put("action",trim(q.optString("action_text"),900));x.put("intent",q.optString("intent_type","livre"));x.put("priority",q.optInt("priority",0));enrichControl(x,actorId);}catch(Exception ignored){AppLog.ignored("MasterCognitiveEngine","Falha tolerada; a execução continuou.",ignored);}out.put(x);}return out;}JSONArray out=new JSONArray();try{String raw=action==null?"":action.trim();if(raw.length()>0){String actor=actorFromText(raw);JSONObject x=new JSONObject().put("actor",actor).put("action",trim(raw,1200)).put("intent",inferIntent(raw)).put("priority",0);JSONObject hero=findHero(actor);long actorId=hero.optLong("id",0);if(actorId>0)x.put("actor_id",actorId);enrichControl(x,actorId);out.put(x);}}catch(Exception ignored){AppLog.ignored("MasterCognitiveEngine","Falha tolerada; a execução continuou.",ignored);}return out;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}

    private void enrichControl(JSONObject unit,long actorId){/*BR_JSON_WRAP*/try{try{if(actorId<=0){unit.put("control_mode","actor_selection_required");return;}JSONObject control=db.getCharacterControl(actorId);unit.put("control_mode",control.optString("control_mode","manual"));unit.put("tactics",parseObject(control.optString("tactics_json","{}")));unit.put("personal_goal",trim(control.optString("personal_goal"),180));unit.put("resource_guard",control.optString("control_mode","manual").equals("manual")?"não gastar recurso limitado sem declaração explícita":"seguir tática e pedir confirmação para recurso limitado");}catch(Exception ignored){AppLog.ignored("MasterCognitiveEngine","Falha tolerada; a execução continuou.",ignored);}}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}
    private JSONObject findHero(String name){String key=normalize(name);if(key.length()==0)return new JSONObject();for(JSONObject h:db.listActiveCharacters())if(key.equals(normalize(h.optString("name"))))return h;return new JSONObject();}
    private String resolvedSceneMode(String normalizedAction){JSONObject combat=db.getCombatState();if(combat.optInt("running",0)==1)return "combate";JSONObject prefs=parseObject(db.getPartyState().optString("session_preferences_json","{}"));String selected=normalize(prefs.optString("scene_mode","Automatico"));if(selected.length()>0&&!selected.equals("automatico")){if(selected.startsWith("explor"))return "exploracao";if(selected.startsWith("convers"))return "conversa";if(selected.startsWith("combat"))return "combate";if(selected.startsWith("viagem"))return "viagem";if(selected.startsWith("descanso"))return "descanso";if(selected.startsWith("tempo livre"))return "tempo_livre";}return sceneMode(normalizedAction);}

    private JSONArray actors(JSONArray units,String normalizedAction){/*BR_JSON_WRAP*/try{JSONArray out=new JSONArray();Set<String> used=new HashSet<String>();for(int i=0;i<units.length();i++){JSONObject u=units.optJSONObject(i);if(u==null)continue;String actor=u.optString("actor").trim();if(actor.length()>0&&used.add(normalize(actor)))out.put(actor);}if(out.length()==0)for(JSONObject h:db.listActiveCharacters()){String name=h.optString("name");if(normalizedAction.contains(normalize(name))&&used.add(normalize(name)))out.put(name);}return out;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}
    private JSONArray causalOrder(JSONArray source){/*BR_JSON_WRAP*/try{List<JSONObject> rows=new ArrayList<JSONObject>();for(int i=0;i<source.length();i++){JSONObject x=source.optJSONObject(i);if(x!=null)rows.add(x);}Collections.sort(rows,new Comparator<JSONObject>(){public int compare(JSONObject a,JSONObject b){int pa=phase(a.optString("intent")),pb=phase(b.optString("intent"));if(pa!=pb)return Integer.compare(pa,pb);return Integer.compare(b.optInt("priority"),a.optInt("priority"));}});JSONArray out=new JSONArray();for(int i=0;i<rows.size();i++){JSONObject x=rows.get(i);try{x.put("causal_order",i+1);x.put("can_parallelize",i>0&&phase(x.optString("intent"))==phase(rows.get(i-1).optString("intent")));}catch(Exception ignored){AppLog.ignored("MasterCognitiveEngine","Falha tolerada; a execução continuou.",ignored);}out.put(x);}return out;}catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException(e);}}
    private String actorFromText(String raw){String n=normalize(raw);for(JSONObject h:db.listActiveCharacters()){String name=h.optString("name");if(n.startsWith(normalize(name)+" ")||n.contains(normalize(name)+" "))return name;}return "";}
    private static int phase(String intent){String n=normalize(intent);if(n.contains("percepc")||n.contains("investig"))return 1;if(n.contains("apoio")||n.contains("prepar"))return 2;if(n.contains("social"))return 3;if(n.contains("movimento")||n.contains("viagem"))return 4;if(n.contains("ataque")||n.contains("magia"))return 5;return 3;}
    private static String inferIntent(String action){String n=normalize(action);if(contains(n,"ataco","golpe","disparo","mato"))return "ataque";if(contains(n,"conjuro","magia","feitiço"))return "magia";if(contains(n,"observo","examino","procuro","investigo"))return "percepcao";if(contains(n,"converso","pergunto","negocio","intimido"))return "social";if(contains(n,"viajo","caminho","avanço","entro","saio"))return "movimento";if(contains(n,"ajudo","protejo","cubro","preparo"))return "apoio";return "livre";}
    private static String sceneMode(String n){if(contains(n,"ataco","combate","iniciativa","golpe","disparo","inimigo"))return "combate";if(contains(n,"converso","pergunto","negocio","persuado","interrogo","falo"))return "conversa";if(contains(n,"viajo","marcho","caminho","rota","acampo"))return "viagem";if(contains(n,"descanso","durmo","vigia","acampamento"))return "descanso";if(contains(n,"compro","vendo","treino","fabrico","pesquiso","tempo livre"))return "tempo_livre";return "exploracao";}
    private static int tension(String n,JSONObject scene,JSONObject runtime,String mode){int t=runtime.optInt("tension",0);if("combate".equals(mode))t=Math.max(t,80);else if(normalize(scene.optString("danger")).contains("alto"))t=Math.max(t,65);else t=Math.max(10,t-8);if(contains(n,"fuga","persegue","armadilha","morte","desabar"))t+=15;if(contains(n,"descanso","seguro","calma"))t-=20;return Math.max(0,Math.min(100,t));}
    private static String sceneGoal(String mode,JSONObject scene,int tension){String objective=scene.optString("objective").trim();if(objective.length()>0)return objective;if(mode.equals("combate"))return "Resolver a ameaça sem perder a posição e os recursos do grupo.";if(mode.equals("conversa"))return "Fazer a relação ou a informação mudar de forma concreta.";if(mode.equals("viagem"))return "Avançar a rota com custo, descoberta ou decisão relevante.";if(mode.equals("descanso"))return "Recuperar recursos e verificar vigias, conversas e riscos do acampamento.";return tension>55?"Clarificar o perigo e oferecer uma decisão significativa.":"Fazer a exploração revelar algo concreto sem forçar uma rolagem.";}
    private static String pacing(String mode,int tension){if(mode.equals("combate")||tension>=75)return "curto, urgente e causal";if(mode.equals("conversa"))return "troca breve, reação autêntica e espaço para resposta";if(mode.equals("viagem"))return "elipse do percurso e foco apenas no que muda";return "sensorial, progressivo e sem resumo da cena anterior";}
    private static boolean contains(String n,String... vs){for(String v:vs)if(n.contains(normalize(v)))return true;return false;}
    private static JSONArray parseArray(String raw){try{return new JSONArray(raw==null?"[]":raw);}catch(Exception e){return new JSONArray();}}
    private static JSONObject parseObject(String raw){try{return new JSONObject(raw==null?"{}":raw);}catch(Exception e){return new JSONObject();}}
    private static String trim(String v,int max){String s=v==null?"":v.trim();return s.length()<=max?s:s.substring(0,max)+"…";}
    private static String normalize(String value){if(value==null)return "";String n=Normalizer.normalize(value.toLowerCase(new Locale("pt","BR")),Normalizer.Form.NFD).replaceAll("\\p{M}","");return n.replaceAll("[^a-z0-9]+"," ").trim();}
}
